      @questions = @quiz.questions.where(active: true).includes(:options).to_a
      @total = @questions.size
      @score = bounded_score
      @finished = params[:finished].present? || (@total.positive? && question_index >= @total)

      return if @total.zero?

      @index = [[question_index, 0].max, @total - 1].min
      @question = @questions[@index]
      @picked_option = picked_option
      @answered = @picked_option.present?
      @picked_correct = @answered && @picked_option.correct?
      @score_after_pick = @score + (@picked_correct ? 1 : 0)
      @last_question = @index == @total - 1
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:quiz_id])
    end

    def question_index
      params[:question].to_i
    end

    def bounded_score
      [[params[:score].to_i, 0].max, @total].min
    end

    def picked_option
      return nil if params[:picked].blank?

      @question.options.find { |option| option.id == params[:picked].to_i }
    end
  end
end
